class GymMember {private static int enrolled=2000;private final int membershipNumber;private int feesPaid;public GymMember(int monthlyFee){if(monthlyFee<=0)throw new IllegalArgumentException();membershipNumber=++enrolled;}public int getMembershipNumber(){return membershipNumber-2000;}public void payFee(int n){if(n<=0)throw new IllegalArgumentException();feesPaid+=n;}public void payFee(int n,String mode){if(mode==null||mode.isBlank())throw new IllegalArgumentException();payFee(n);}public int getFeesPaid(){return feesPaid;}public static int getMembersEnrolled(){return enrolled-2000;}}
class GroupClassMember extends GymMember {private String className;public GroupClassMember(int fee,String c){super(fee);className=c;}}
public class Problem5_MembershipNumbersReferralAudit {static boolean isValidReferralCode(String s){return s!=null&&s.length()==4&&s.charAt(0)=='G'&&Character.isDigit(s.charAt(1))&&Character.isDigit(s.charAt(2))&&Character.isUpperCase(s.charAt(3));}static String processWeeklyCheckIn(GymMember[] a){int p=0,n=0,g=0,i=0;for(GymMember m:a){if(m==null){n++;continue;}p++;if(m instanceof GroupClassMember)g++;else i++;}return p+" processed | "+n+" null skipped | "+g+" group | "+i+" individual";}public static void main(String[]x){GymMember m=new GymMember(1000);System.out.println(m.getMembershipNumber());System.out.println(isValidReferralCode("G45B"));System.out.println(processWeeklyCheckIn(new GymMember[]{new GroupClassMember(1500,"Zumba"),null,new GymMember(1000)}));}}